import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
import { Circle } from "@remotion/shapes";

{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type TimelineProcessProps = Record<string, any>;

const TimelineProcess: React.FC<TimelineProcessProps> = ({
  backgroundColor = "#1a0f0a",
  transparentBackground = false,
  primaryColor = "#fdbb75",
  textColor = "#ffffff",
  lineColor = "#cccccc",
  durationInSeconds = 10,
  circleSize = 120,
  fontSize = 32,
  steps = ["Niche 1", "Niche 2", "Niche 3", "Niche 4", "Niche 5"],
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color handling
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Layout constants
  const numSteps = steps.length;
  const contentWidth = width * 0.8;
  const startX = (width - contentWidth) / 2;
  const centerY = height / 2;
  const circleRadius = circleSize / 2;
  
  // Calculate spacing
  // Total width = (numSteps * circleSize) + ((numSteps - 1) * gap)
  // gap = (Total width - (numSteps * circleSize)) / (numSteps - 1)
  const gap = numSteps > 1 
    ? (contentWidth - (numSteps * circleSize)) / (numSteps - 1) 
    : 0;

  // Animation constants
  const stepDelay = 15; // Frames between each step start
  const lineDuration = 20; // Frames for line to draw

  // Helper to get position of Nth circle
  const getCircleX = (index: number) => startX + index * (circleSize + gap) + circleRadius;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        fontFamily: "Inter, sans-serif",
      }}
    >
      <AbsoluteFill>
        {steps.map((label, index) => {
          // Calculate start frame for this step
          const startFrame = index * stepDelay;
          
          // Circle Pop Animation
          const scale = spring({
            frame: frame - startFrame,
            fps,
            config: { stiffness: 200, damping: 15 },
          });

          // Text Fade/Slide Animation
          const textOpacity = interpolate(
            frame - startFrame - 10,
            [0, 20],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );
          
          const textTranslateY = interpolate(
            frame - startFrame - 10,
            [0, 20],
            [20, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Line Animation (Line connects current step to NEXT step)
          // Only render line if it's not the last step
          const isLast = index === steps.length - 1;
          const lineStartFrame = startFrame + 10;
          
          const lineProgress = spring({
            frame: frame - lineStartFrame,
            fps,
            config: { stiffness: 80, damping: 20 },
          });
          
          const lineWidth = interpolate(
            lineProgress,
            [0, 1],
            [0, gap],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Positions
          const cx = getCircleX(index);
          const cy = centerY;

          return (
            <React.Fragment key={index}>
              {/* Connecting Line (drawn to the right of the circle) */}
              {!isLast && (
                <div
                  style={{
                    position: "absolute",
                    left: cx + circleRadius - 2, // Slight overlap to prevent gap
                    top: cy - 2, // Centered vertically (4px height)
                    width: Math.max(0, lineWidth),
                    height: 4,
                    backgroundColor: lineColor,
                    boxShadow: `0 0 8px ${lineColor}`,
                    borderRadius: 2,
                    zIndex: 0, // Behind circles
                    transformOrigin: "left center",
                  }}
                />
              )}

              {/* Circle Group */}
              <div
                style={{
                  position: "absolute",
                  left: cx - circleRadius,
                  top: cy - circleRadius,
                  width: circleSize,
                  height: circleSize,
                  transform: `scale(${scale})`,
                  zIndex: 1, // On top of lines
                }}
              >
                <Circle
                  radius={circleRadius}
                  fill={primaryColor}
                  style={{
                    filter: `drop-shadow(0 4px 10px rgba(0,0,0,0.3))`,
                  }}
                />
                
                {/* Number inside circle */}
                <div
                  style={{
                    position: "absolute",
                    top: 0,
                    left: 0,
                    width: "100%",
                    height: "100%",
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    fontSize: fontSize * 1.5,
                    fontWeight: 700,
                    color: "#000000",
                  }}
                >
                  {index + 1}
                </div>
              </div>

              {/* Label Text */}
              <div
                style={{
                  position: "absolute",
                  // Center the text area relative to the circle center (cx).
                  // Width is circleSize * 3, so offset left by half width (circleSize * 1.5).
                  left: cx - circleSize * 1.5,
                  width: circleSize * 3,
                  top: cy + circleRadius + 20,
                  textAlign: "center",
                  opacity: textOpacity,
                  transform: `translateY(${textTranslateY}px)`,
                  color: textColor,
                  fontSize: fontSize,
                  fontWeight: 500,
                }}
              >
                {label}
              </div>
            </React.Fragment>
          );
        })}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default TimelineProcess;